'use strict';

function orderSummary(items) {
  var total = 0;
  var names = [];
  items.forEach(function (item) {
    total += item.qty;
    names.push(item.name);
  });
  return names.join(',') + ':' + total;
}

function orderMerge(defaults, overrides) {
  return Object.assign({}, defaults, overrides, { merged: true });
}

function orderKeys(obj) {
  var out = [];
  Object.keys(obj).forEach(function (k) {
    out.push(k + '=' + obj[k]);
  });
  return out.sort();
}

function orderBuckets(values) {
  var buckets = new Array();
  var index = new Object();
  for (var i = 0; i < values.length; i++) {
    var key = values[i] % 3;
    if (index[key] === undefined) {
      index[key] = buckets.length;
      buckets.push([]);
    }
    buckets[index[key]].push(values[i]);
  }
  return buckets;
}

module.exports = { orderSummary, orderMerge, orderKeys, orderBuckets };

