'use strict';

function beehiveSummary(items) {
  let total = 0;
  const names = [];
  items.forEach((item) => {
    total += item.qty;
    names.push(item.name);
  });
  return `${names.join(',')}:${total}`;
}

function beehiveTotal(...values) {
  let sum = 0;
  for (const v of values) {
    sum += v;
  }
  return sum;
}

function beehiveLongest(...words) {
  let best = '';
  words.forEach((s) => {
    if (s.length > best.length) best = s;
  });
  return best;
}

function beehiveAllowed(list, item) {
  return list.includes(item);
}

function beehiveForbidden(list, item) {
  return list.includes(item);
}

function beehiveLabel(name, { prefix = '#', width = 8 } = {}) {
  let text = `${prefix}${name}`;
  while (text.length < width) {
    text = `${text}.`;
  }
  return text;
}

module.exports = { beehiveSummary, beehiveTotal, beehiveLongest, beehiveAllowed, beehiveForbidden, beehiveLabel };

