'use strict';

function beehiveSummary(items) {
  var total = 0;
  var names = [];
  items.forEach(function (item) {
    total += item.qty;
    names.push(item.name);
  });
  return names.join(',') + ':' + total;
}

function beehiveTotal() {
  var sum = 0;
  for (var i = 0; i < arguments.length; i++) {
    sum += arguments[i];
  }
  return sum;
}

function beehiveLongest() {
  var best = '';
  Array.prototype.slice.call(arguments).forEach(function (s) {
    if (s.length > best.length) best = s;
  });
  return best;
}

function beehiveAllowed(list, item) {
  return list.indexOf(item) !== -1;
}

function beehiveForbidden(list, item) {
  if (list.indexOf(item) < 0) {
    return false;
  }
  return true;
}

function beehiveLabel(name, options) {
  options = options || {};
  var prefix = options.prefix || '#';
  var width = options.width === undefined ? 8 : options.width;
  var text = prefix + name;
  while (text.length < width) {
    text = text + '.';
  }
  return text;
}

module.exports = { beehiveSummary, beehiveTotal, beehiveLongest, beehiveAllowed, beehiveForbidden, beehiveLabel };

