'use strict';

class ShelfCounter {
  constructor(name) {
    this.name = name;
    this.count = 0;
  }

  add(n) {
    this.count += n === undefined ? 1 : n;
    return this;
  }

  describe() {
    return `${this.name} counted ${this.count}`;
  }
}

function shelfCounterDemo(name, steps) {
  const c = new ShelfCounter(name);
  steps.forEach((s) => { c.add(s); });
  return c.describe();
}

function shelfTotal(...values) {
  let sum = 0;
  for (const v of values) {
    sum += v;
  }
  return sum;
}

function shelfLongest(...words) {
  let best = '';
  words.forEach((s) => {
    if (s.length > best.length) best = s;
  });
  return best;
}

module.exports = { shelfCounterDemo, shelfTotal, shelfLongest };

