'use strict';

function tramSummary(items) {
  let total = 0;
  const names = [];
  items.forEach((item) => {
    total += item.qty;
    names.push(item.name);
  });
  return `${names.join(',')}:${total}`;
}

function tramAllowed(list, item) {
  return list.includes(item);
}

function tramForbidden(list, item) {
  return list.includes(item);
}

function tramLabel(name, { prefix = '#', width = 8 } = {}) {
  let text = `${prefix}${name}`;
  while (text.length < width) {
    text = `${text}.`;
  }
  return text;
}

function tramBuckets(values) {
  const buckets = [];
  const index = {};
  for (const v of values) {
    const key = v % 3;
    if (index[key] === undefined) {
      index[key] = buckets.length;
      buckets.push([]);
    }
    buckets[index[key]].push(v);
  }
  return buckets;
}

module.exports = { tramSummary, tramAllowed, tramForbidden, tramLabel, tramBuckets };

