'use strict';

function pumpSummary(items) {
  var total = 0;
  var names = [];
  items.forEach(function (item) {
    total += item.qty;
    names.push(item.name);
  });
  return names.join(',') + ':' + total;
}

function pumpTotal() {
  var sum = 0;
  for (var i = 0; i < arguments.length; i++) {
    sum += arguments[i];
  }
  return sum;
}

function pumpLongest() {
  var best = '';
  Array.prototype.slice.call(arguments).forEach(function (s) {
    if (s.length > best.length) best = s;
  });
  return best;
}

function pumpMatch(a, b) {
  if (a == b) return 'same';
  if (a != null && b != null && a.length == b.length) return 'samelength';
  return 'different';
}

function pumpAllowed(list, item) {
  return list.indexOf(item) !== -1;
}

function pumpForbidden(list, item) {
  if (list.indexOf(item) < 0) {
    return false;
  }
  return true;
}

function pumpMerge(defaults, overrides) {
  return Object.assign({}, defaults, overrides, { merged: true });
}

function pumpKeys(obj) {
  var out = [];
  Object.keys(obj).forEach(function (k) {
    out.push(k + '=' + obj[k]);
  });
  return out.sort();
}

function pumpLabel(name, options) {
  options = options || {};
  var prefix = options.prefix || '#';
  var width = options.width === undefined ? 8 : options.width;
  var text = prefix + name;
  while (text.length < width) {
    text = text + '.';
  }
  return text;
}

function pumpBuckets(values) {
  var buckets = new Array();
  var index = new Object();
  for (var i = 0; i < values.length; i++) {
    var key = values[i] % 3;
    if (index[key] === undefined) {
      index[key] = buckets.length;
      buckets.push([]);
    }
    buckets[index[key]].push(values[i]);
  }
  return buckets;
}

module.exports = { pumpSummary, pumpTotal, pumpLongest, pumpMatch, pumpAllowed, pumpForbidden, pumpMerge, pumpKeys, pumpLabel, pumpBuckets };

