'use strict';

function loomSummary(items) {
  let total = 0;
  const names = [];
  items.forEach((item) => {
    total += item.qty;
    names.push(item.name);
  });
  return `${names.join(',')}:${total}`;
}

class LoomCounter {
  constructor(name) {
    this.name = name;
    this.count = 0;
  }

  add(n) {
    this.count += n === undefined ? 1 : n;
    return this;
  }

  describe() {
    return `${this.name} counted ${this.count}`;
  }
}

function loomCounterDemo(name, steps) {
  const c = new LoomCounter(name);
  steps.forEach((s) => { c.add(s); });
  return c.describe();
}

function loomMerge(defaults, overrides) {
  return { ...defaults, ...overrides, merged: true };
}

function loomKeys(obj) {
  return Object.entries(obj).map(([k, v]) => `${k}=${v}`).sort();
}

function loomLabel(name, { prefix = '#', width = 8 } = {}) {
  let text = `${prefix}${name}`;
  while (text.length < width) {
    text = `${text}.`;
  }
  return text;
}

module.exports = { loomSummary, loomCounterDemo, loomMerge, loomKeys, loomLabel };

