  let sum = 0;
  for (const v of values) {
    sum += v;
  }
  return sum;
}

function kilnLongest(...words) {
  let best = '';
  words.forEach((s) => {
    if (s.length > best.length) best = s;
  });
  return best;
}

function kilnMatch(a, b) {
  if (a === b) return 'same';
  if (a !== null && b !== null && a.length === b.length) return 'samelength';
  return 'different';
}

function kilnMerge(defaults, overrides) {
  return { ...defaults, ...overrides, merged: true };
}

function kilnKeys(obj) {
  return Object.entries(obj).map(([k, v]) => `${k}=${v}`).sort();
}

function kilnLabel(name, { prefix = '#', width = 8 } = {}) {
  let text = `${prefix}${name}`;
  while (text.length < width) {
    text = `${text}.`;
  }
  return text;
}

module.exports = { kilnSummary, kilnCounterDemo, kilnTotal, kilnLongest, kilnMatch, kilnMerge, kilnKeys, kilnLabel };

