'use strict';

function orderSummary(items) {
  let total = 0;
  const names = [];
  items.forEach((item) => {
    total += item.qty;
    names.push(item.name);
  });
  return `${names.join(',')}:${total}`;
}

class OrderCounter {
  constructor(name) {
    this.name = name;
    this.count = 0;
  }

  add(n) {
    this.count += n === undefined ? 1 : n;
    return this;
  }

  describe() {
    return `${this.name} counted ${this.count}`;
  }
}

function orderCounterDemo(name, steps) {
  const c = new OrderCounter(name);
  steps.forEach((s) => { c.add(s); });
  return c.describe();
}

function orderTotal(...values) {
  let sum = 0;
  for (const v of values) {
    sum += v;
  }
  return sum;
}

function orderLongest(...words) {
  let best = '';
  words.forEach((s) => {
    if (s.length > best.length) best = s;
  });
  return best;
}

module.exports = { orderSummary, orderCounterDemo, orderTotal, orderLongest };

