'use strict';

function orderSummary(items) {
  var total = 0;
  var names = [];
  items.forEach(function (item) {
    total += item.qty;
    names.push(item.name);
  });
  return names.join(',') + ':' + total;
}

function OrderCounter(name) {
  this.name = name;
  this.count = 0;
}

OrderCounter.prototype.add = function add(n) {
  this.count += n === undefined ? 1 : n;
  return this;
};

OrderCounter.prototype.describe = function describe() {
  return this.name + ' counted ' + this.count;
};

function orderCounterDemo(name, steps) {
  const c = new OrderCounter(name);
  steps.forEach(function (s) { c.add(s); });
  return c.describe();
}

function orderTotal() {
  var sum = 0;
  for (var i = 0; i < arguments.length; i++) {
    sum += arguments[i];
  }
  return sum;
}

function orderLongest() {
  var best = '';
  Array.prototype.slice.call(arguments).forEach(function (s) {
    if (s.length > best.length) best = s;
  });
  return best;
}

module.exports = { orderSummary, OrderCounter, orderCounterDemo, orderTotal, orderLongest };

