'use strict';

function beehiveSummary(items) {
  let total = 0;
  const names = [];
  items.forEach((item) => {
    total += item.qty;
    names.push(item.name);
  });
  return `${names.join(',')}:${total}`;
}

function beehiveMatch(a, b) {
  if (a === b) return 'same';
  if (a !== null && b !== null && a.length === b.length) return 'samelength';
  return 'different';
}

function beehiveMerge(defaults, overrides) {
  return { ...defaults, ...overrides, merged: true };
}

function beehiveKeys(obj) {
  return Object.entries(obj).map(([k, v]) => `${k}=${v}`).sort();
}

function beehiveLabel(name, { prefix = '#', width = 8 } = {}) {
  let text = `${prefix}${name}`;
  while (text.length < width) {
    text = `${text}.`;
  }
  return text;
}

function beehiveBuckets(values) {
  const buckets = [];
  const index = {};
  for (const v of values) {
    const key = v % 3;
    if (index[key] === undefined) {
      index[key] = buckets.length;
      buckets.push([]);
    }
    buckets[index[key]].push(v);
  }
  return buckets;
}

module.exports = { beehiveSummary, beehiveMatch, beehiveMerge, beehiveKeys, beehiveLabel, beehiveBuckets };

