'use strict';

function beehiveSummary(items) {
  var total = 0;
  var names = [];
  items.forEach(function (item) {
    total += item.qty;
    names.push(item.name);
  });
  return names.join(',') + ':' + total;
}

function beehiveMatch(a, b) {
  if (a == b) return 'same';
  if (a != null && b != null && a.length == b.length) return 'samelength';
  return 'different';
}

function beehiveMerge(defaults, overrides) {
  return Object.assign({}, defaults, overrides, { merged: true });
}

function beehiveKeys(obj) {
  var out = [];
  Object.keys(obj).forEach(function (k) {
    out.push(k + '=' + obj[k]);
  });
  return out.sort();
}

function beehiveLabel(name, options) {
  options = options || {};
  var prefix = options.prefix || '#';
  var width = options.width === undefined ? 8 : options.width;
  var text = prefix + name;
  while (text.length < width) {
    text = text + '.';
  }
  return text;
}

function beehiveBuckets(values) {
  var buckets = new Array();
  var index = new Object();
  for (var i = 0; i < values.length; i++) {
    var key = values[i] % 3;
    if (index[key] === undefined) {
      index[key] = buckets.length;
      buckets.push([]);
    }
    buckets[index[key]].push(values[i]);
  }
  return buckets;
}

module.exports = { beehiveSummary, beehiveMatch, beehiveMerge, beehiveKeys, beehiveLabel, beehiveBuckets };

